// This module is the fixed external boundary for the world protocol. Internal
// rule and entity-module structure is intentionally kept behind this adapter.

import { WorldProtocol } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceFen1, advanceFen2, recoverFen } from "./fen/rules";
import { advanceOsk1 } from "./osk/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(state: WorldState, operationDisplayName: string) {
    const operations: Record<string, (world: WorldState) => WorldState> = {
      advanceVok1,
      advanceVok2,
      advanceZef1,
      advanceZef2,
      advanceTal1,
      advanceOsk1,
      advanceFen1,
      advanceFen2,
      recoverFen,
    };
    const operation = operations[operationDisplayName];

    if (!operation) {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true, newState: operation(state) };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    const entityStates: Record<string, string> = {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
    return entityStates[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
  },
};
